const $=q=>document.querySelector(q),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),number=(n,d=1)=>Number(n).toLocaleString('es-CO',{maximumFractionDigits:d}),M=materials();
let section='buildings',selected='camp',era=0,level=1,category='all',search='',yaw=Math.PI/4,currentModel=null,dirty=true,lab='corridor';
const scene=new T.Scene(),light=new T.DirectionalLight('#fff0d6',3);light.position.set(-4,7,5);scene.add(light,new T.HemisphereLight('#f0f1dd','#5e6c4d',2.4));const camera=new T.OrthographicCamera(),canvas=$('#preview');
let renderer;try{renderer=new T.WebGLRenderer({canvas,antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;$('#renderer-status').textContent='Modelos 3D originales · WebGL 2';}catch(e){$('#renderer-status').textContent='Este visor necesita WebGL 2';$('#export-sheet').disabled=true;$('.stage').insertAdjacentHTML('beforeend','<p class="error">No se pudo iniciar el visor 3D. El estándar y el laboratorio siguen disponibles.</p>');}
const ground=part(scene,'ground',M.grass,0,-.04,0,4.2,1,4.2);ground.visible=false;const thumbRenderer=renderer?new T.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true}):null,thumbScene=new T.Scene(),thumbCamera=new T.OrthographicCamera(-2.25,2.25,1.69,-1.69,.1,40);thumbCamera.position.set(4,3.4,5);thumbCamera.lookAt(0,.75,0);thumbScene.add(new T.HemisphereLight('#f1f1df','#5d6a4e',2.4));const tl=new T.DirectionalLight('#fff0d6',3);tl.position.set(-4,7,5);thumbScene.add(tl);if(thumbRenderer){thumbRenderer.setSize(256,192);thumbRenderer.outputColorSpace=T.SRGBColorSpace;thumbRenderer.toneMapping=T.ACESFilmicToneMapping;thumbRenderer.toneMappingExposure=1.15;}
const thumbs=new Map();
function registry(){return section==='buildings'?BUILDINGS:section==='units'?UNITS:section==='npcs'?Object.fromEntries(NPCS.map(n=>[n.id,n])):Object.fromEntries(Object.entries(CIVILIZATIONS).map(([id,c])=>[id,{id,name:SPECIES[id].name,...c,status:'campaign',era:0}]));}
function modelFor(kind,id,e,l){if(kind==='buildings')return designBuilding(id,e,l,M);if(kind==='civilizations')return designCivilization(id,e,l,M);if(kind==='npcs'){const g=designUnit(id,e,l,M);return g;}return designUnit(id,e,l,M);}
function thumbnail(kind,id,e,l){const key=[kind,id,e,l].join(':');if(thumbs.has(key))return thumbs.get(key);const model=modelFor(kind,id,e,l);if(kind==='units'&&['jeep','bulwark','missile','cavalry','settler','archer','spearman'].includes(UNITS[id]?.model))model.scale.setScalar(1.3);thumbScene.add(model);thumbRenderer.render(thumbScene,thumbCamera);const url=thumbRenderer.domElement.toDataURL('image/png');thumbScene.remove(model);thumbs.set(key,url);if(thumbs.size>180)thumbs.delete(thumbs.keys().next().value);return url;}
function renderView(){if(!renderer||!currentModel||$('#catalog').hidden)return;const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setSize(r.width,r.height,false);const aspect=r.width/r.height,half=2.3;Object.assign(camera,{left:-half*aspect,right:half*aspect,top:half,bottom:-half,near:.1,far:50});camera.position.set(Math.sin(yaw)*7,4.5,Math.cos(yaw)*7);camera.lookAt(0,.8,0);camera.updateProjectionMatrix();renderer.render(scene,camera);dirty=false;}
function renderLibrary(){const all=Object.values(registry()),items=all.filter(v=>(category==='all'||v.category===category||v.domain===category)&&(!search||[v.name,v.function,v.role,v.inputs,v.outputs,v.staff,v.quest].join(' ').toLocaleLowerCase('es').includes(search)));$('#library-count').textContent=items.length+' de '+all.length+' diseños';$('#library-list').innerHTML=items.map(v=>`<button data-item="${esc(v.id)}" class="${v.id===selected?'active':''}">${esc(v.name)}<small>${section==='buildings'?esc(CATEGORIES[v.category])+' · ':''}${esc(STATUS[v.status]||'Plano de expansión')}</small></button>`).join('')||'<p>No hay diseños con este filtro.</p>';}
const fact=(label,value)=>`<div class="fact"><small>${esc(label)}</small>${esc(value)}</div>`;
function renderItem(){if(!renderer)return;const s=registry()[selected];if(!s)return;if(currentModel)scene.remove(currentModel);currentModel=modelFor(section,selected,era,level);scene.add(currentModel);const active=s.status==='campaign';$('#status').textContent=(STATUS[s.status]||'Plano de expansión')+(section==='civilizations'?' · REVELACIONES DE PUEBLOS':'');$('#status').classList.toggle('blueprint',!active);$('#item-name').textContent=s.name;$('#item-role').textContent=s.function||s.role||s.quest||s.shape;$('#era').value=era;$('#level').value=level;
 let facts='';if(section==='buildings'){const p=levelProfile(selected,level,era);facts=fact('NECESITA',s.inputs)+fact('APORTA',s.outputs)+fact('PERSONAL',s.staff)+fact('ACCESO',s.access)+fact('ESTUDIO DE DISEÑO',s.study)+fact('APERTURA DE CAMPAÑA',s.status==='campaign'?'Era '+(s.era+1)+' · '+ERAS[s.era].name:'Plano · era objetivo '+(s.era+1));if(active){const stats=buildingStats({level,tier:era},STRUCTURES[selected]);facts+=fact('PRESTACIONES DE CAMPAÑA',number(stats.hp,0)+' integridad'+(stats.capacity?' · '+number(stats.capacity,0)+' plazas':'')+' · ×'+number(stats.output,2)+' rendimiento');}facts+=fact('ARQUITECTURA',p.style+' · '+p.material);$('#level-description').textContent='Nivel '+level+' · '+p.name+' — '+p.change+(era<s.era?' · Vista de diseño anterior a su desbloqueo.':'');}
 else if(section==='units'){facts=fact('PAPEL',s.role)+fact('DOMINIO',s.domain)+fact('ORIGEN',BUILDINGS[s.facility]?.name||s.facility)+fact('PROGRESIÓN',UNIT_LEVELS[level-1].change);$('#level-description').textContent='Grado '+level+' · '+UNIT_LEVELS[level-1].name+' — equipo entrenable dentro de la era.';}
 else if(section==='npcs'){facts=fact('LUGAR DE ORIGEN',BUILDINGS[s.facility]?.name||s.facility)+fact('PETICIÓN',s.quest)+fact('DECISIÓN Y MORALIDAD',s.morality)+fact('ESTADO','Visitante activo, encargos con pago y moralidad');$('#level-description').textContent='Grado '+level+' · '+UNIT_LEVELS[level-1].name+' — '+UNIT_LEVELS[level-1].change;}
 else{facts=fact('MATERIALES',s.material)+fact('SILUETA',s.shape)+fact('CONTACTO',s.mission)+fact('TRANSPORTE',s.transport)+fact('DEFENSA',s.defense)+fact('CONDICIÓN DE CAMPAÑA',SPECIES[selected].description);$('#level-description').textContent='Nivel '+level+' · '+LEVELS[level-1].change+' · Arquitectura de asentamiento por pueblo';}
 $('#item-facts').innerHTML=facts;$('#level-grid').innerHTML=Array.from({length:10},(_,i)=>{const n=i+1;return`<button class="level-card ${n===level?'active':''}" data-level="${n}"><img src="${thumbnail(section,selected,era,n)}" alt="${esc(s.name)} · nivel ${n} · ${esc(ERAS[era].name)}"><strong>${section==='units'||section==='npcs'?'Grado':'Nivel'} ${n}</strong><small>${(section==='units'||section==='npcs'?UNIT_LEVELS:LEVELS)[i].name}</small></button>`;}).join('');dirty=true;renderView();}
function chooseSection(kind){if(!['buildings','units','npcs','civilizations','engineering','standard'].includes(kind))return;section=kind;$('.tabs .active')?.classList.remove('active');$('[data-section="'+kind+'"]').classList.add('active');$('#catalog').hidden=['engineering','standard'].includes(kind);$('#engineering').hidden=kind!=='engineering';$('#standard').hidden=kind!=='standard';if(kind==='engineering'){renderLab();return;}if(kind==='standard')return;category='all';search='';$('#search').value='';selected=Object.keys(registry())[0];$('#category-label').hidden=!['buildings','units'].includes(kind);const cats=kind==='buildings'?CATEGORIES:{all:'Todos',Civil:'Civiles',Tierra:'Tierra',Mar:'Mar',Aire:'Aire',Logística:'Logística'};$('#category').innerHTML=Object.entries(cats).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');renderLibrary();renderItem();}
$('#counts').innerHTML=[[Object.keys(BUILDINGS).length,'edificios'],[Object.keys(UNITS).length,'tropas y transportes'],[NPCS.length,'roles NPC'],[6,'pueblos'],[40,'eras · 10 niveles']].map(([n,t])=>`<span><b>${n}</b>${t}</span>`).join('');$('#era').innerHTML=ERAS.map((e,i)=>`<option value="${i}">${i+1} · ${esc(e.name)}</option>`).join('');$('#level').innerHTML=LEVELS.map((l,i)=>`<option value="${i+1}">${i+1} / 10</option>`).join('');
document.addEventListener('click',async e=>{const t=e.target.closest('[data-section],[data-item],[data-level],[data-lab]');if(!t)return;if(t.dataset.section)chooseSection(t.dataset.section);if(t.dataset.item){selected=t.dataset.item;era=Math.max(era,registry()[selected].era||0);renderLibrary();renderItem();}if(t.dataset.level){level=Number(t.dataset.level);renderItem();}if(t.dataset.lab){lab=t.dataset.lab;renderLab();}});$('#search').addEventListener('input',e=>{search=e.target.value.trim().toLocaleLowerCase('es');renderLibrary();});$('#category').addEventListener('change',e=>{category=e.target.value;renderLibrary();});$('#era').addEventListener('change',e=>{era=Number(e.target.value);renderItem();});$('#level').addEventListener('change',e=>{level=Number(e.target.value);renderItem();});$('#reset-view').addEventListener('click',()=>{yaw=Math.PI/4;dirty=true;});let drag=null;canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,yaw};});canvas.addEventListener('pointermove',e=>{if(drag){yaw=drag.yaw+(e.clientX-drag.x)*.009;dirty=true;}});canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();yaw+=(e.key==='ArrowRight'?1:-1)*Math.PI/8;dirty=true;}});addEventListener('resize',()=>dirty=true);
export async function exportSheet(kind,id,e){if(!renderer)throw Error('WebGL 2 requerido');const data=kind==='buildings'?BUILDINGS:kind==='units'?UNITS:kind==='npcs'?Object.fromEntries(NPCS.map(n=>[n.id,n])):Object.fromEntries(Object.entries(CIVILIZATIONS).map(([key,c])=>[key,{name:SPECIES[key].name,...c}]));const s=data[id];if(!s||!Number.isInteger(e)||e<0||e>=ERAS.length)throw Error('Lámina inválida');const out=document.createElement('canvas');out.width=1600;out.height=900;const c=out.getContext('2d');c.fillStyle='#142c2f';c.fillRect(0,0,1600,900);c.fillStyle='#e4e7d0';c.font='32px Georgia';c.fillText('AURALIS · '+s.name,35,53);c.font='15px sans-serif';c.fillStyle='#b3c7b8';c.fillText('Era '+(e+1)+' · '+ERAS[e].name+' · '+(STATUS[s.status]||'Plano de expansión'),35,86);for(let i=0;i<10;i++){const x=25+(i%5)*315,y=120+Math.floor(i/5)*365,img=new Image();img.src=thumbnail(kind,id,e,i+1);await img.decode();c.fillStyle='#d4d8bd';c.fillRect(x,y,290,254);c.drawImage(img,x,y+12,290,218);c.fillStyle='#e4e7d0';c.font='19px sans-serif';c.fillText((kind==='units'||kind==='npcs'?'Grado ':'Nivel ')+(i+1),x+12,y+282);c.fillStyle='#a7bdb3';c.font='14px sans-serif';c.fillText((kind==='units'||kind==='npcs'?UNIT_LEVELS:LEVELS)[i].name,x+12,y+309);}c.font='12px sans-serif';c.fillStyle='#a7bdb3';c.fillText('Modelos originales 3D · Huella estable · Diez niveles · Diseños integrados en la campaña desde v0.10',35,878);return out.toDataURL('image/png');}
$('#export-sheet').addEventListener('click',async()=>{const b=$('#export-sheet');b.disabled=true;try{const a=document.createElement('a');a.href=await exportSheet(section,selected,era);a.download='auralis-'+selected+'-era-'+(era+1)+'-niveles-1-10.png';a.click();}finally{b.disabled=false;}});
const label=(key,text,value,min,max,step=1)=>`<label>${text}<input name="${key}" type="number" value="${value}" min="${min}" max="${max}" step="${step}" required></label>`,select=(key,text,options,value)=>`<label>${text}<select name="${key}">${Object.entries(options).map(([k,v])=>`<option value="${k}" ${k===value?'selected':''}>${v.name||v}</option>`).join('')}</select></label>`,metric=(n,t)=>`<div class="metric"><strong>${n}</strong><span>${t}</span></div>`,price=c=>'<div class="lab-price">'+Object.entries(c).map(([k,v])=>`<span>${number(v,0)} ${{wood:'madera',stone:'piedra',iron:'hierro'}[k]||k}</span>`).join('')+'</div>';
function bridgeDiagram(o,q){const count=o.supports+2,x0=28,x1=532,y=68,points=Array.from({length:count},(_,i)=>x0+(x1-x0)*i/(count-1)),color=q.ok?'#cdddaf':'#e0ab8e';return '<svg class="bridge-diagram" viewBox="0 0 560 155" role="img" aria-label="Esquema de apoyos y carga del puente"><path d="M15 123H545" stroke="#5b7668" stroke-width="2"/>'+points.map(x=>'<path d="M'+x+' '+y+'L'+(x-8)+' 122H'+(x+8)+'Z" fill="#667f74"/>').join('')+'<path d="M28 '+y+'H532" stroke="'+color+'" stroke-width="11"/><path d="M260 18V47M249 37L260 49L271 37" fill="none" stroke="'+color+'" stroke-width="3"/><rect x="227" y="48" width="67" height="13" rx="4" fill="'+color+'"/><text x="280" y="15" fill="#cbd9c1" font-size="11">'+number(o.vehicle+o.payload)+' t</text><text x="28" y="148" fill="#a7bdb3" font-size="11">'+number(o.length)+' m · '+(o.supports+1)+' luces · '+number(q.span)+' m entre apoyos</text></svg>';}
function renderLab(){document.querySelectorAll('[data-lab]').forEach(b=>b.classList.toggle('active',b.dataset.lab===lab));$('#lab-inputs').innerHTML=lab==='bridge'?select('material','Material equivalente',BRIDGE_MATERIALS,'timber')+label('length','Longitud total · m',20,2,500)+label('width','Ancho · m',4,1,30,.1)+label('supports','Pilas intermedias',2,0,24)+label('girders','Vigas paralelas',6,1,24)+label('beamWidth','Ancho de cada viga · m',.3,.08,2,.01)+label('beamHeight','Altura de cada viga · m',.65,.15,5,.01)+label('vehicle','Vehículo vacío · t',1,0,1000,.1)+label('payload','Carga útil · t',2,0,5000,.1)+label('traffic','Cruces por día',30,1,100000)+label('years','Vida deseada · años',15,1,200)+label('bearing','Capacidad del suelo · kPa',180,20,1000)+select('climate','Exposición',{dry:'Seca',wet:'Húmeda',marine:'Marina'},'dry'):lab==='corridor'?select('mode','Medio de transporte',TRANSPORT_MODES,'cart')+label('length','Distancia · m',1200,10,100000)+label('width','Ancho de la plataforma · m',4,1,30,.1)+label('slope','Pendiente máxima · %',5,0,60,.1)+label('cutDepth','Profundidad media de explanación · m',.2,0,8,.01)+label('cargo','Carga total a transportar · t',24,.01,100000,.01)+select('soil','Terreno',{firm:'Firme',soft:'Blando',rock:'Rocoso'},'firm'):select('type','Defensa',{tower:'Torre',ballista:'Ballestas',cannon:'Artillería',antiair:'Antiaérea',coastal:'Batería costera',shield:'Escudo'},'tower')+label('slope','Pendiente de plataforma · %',4,0,60,.1)+label('bearing','Capacidad del suelo · kPa',180,20,1000)+label('visibility','Sector despejado · grados',240,0,360)+label('supplyDistance','Distancia al suministro · m',300,0,10000)+label('power','Energía disponible · unidades de juego',40,0,10000);calculate();}
function calculate(){const form=$('#lab-form');if(!form.checkValidity()){$('#lab-results').innerHTML='<p class="failed">Revisa los campos fuera de rango. No se ha autorizado ni presupuestado ninguna obra.</p>';return;}const o=Object.fromEntries(new FormData(form).entries());for(const k of Object.keys(o))if(!['mode','material','climate','soil','type'].includes(k))o[k]=Number(o[k]);try{if(lab==='bridge'){const q=bridgeEstimate(o);$('#lab-results').innerHTML=`<h3 class="${q.ok?'passed':'failed'}">${q.ok?'Alternativa viable en el modelo':'Hace falta redimensionar'}</h3>${bridgeDiagram(o,q)}<div class="lab-metrics">${metric(number(q.span)+' m','Luz entre apoyos')}${metric(number(q.capacityPayloadTonnes)+' t','Carga útil máxima por tensión')}${metric(number(q.stressMPa)+' MPa','Tensión calculada')}${metric(number(q.deflectionMm)+' / '+number(q.deflectionLimitMm)+' mm','Flecha / límite L/400')}${metric(number(q.lifeYears)+' años','Vida estimada por tráfico y exposición')}${metric(number(q.groundPressureKPa)+' kPa','Presión equivalente en cimentación')}</div><p>${q.assumptions}</p>${q.reasons.length?'<ul>'+q.reasons.map(r=>'<li class="failed">'+r+'</li>').join('')+'</ul>':''}<h4>Presupuesto de juego</h4>${price(q.cost)}<p>Volúmenes: ${number(q.beamVolume)} m³ de vigas · ${number(q.deckVolume)} m³ de tablero · ${number(q.supportVolume)} m³ equivalentes de apoyos. Vida deseada: ${o.years} años. Añadir pilas también aumenta cimentación y materiales.</p>`;}
 else if(lab==='corridor'){const q=corridorEstimate(o);$('#lab-results').innerHTML=`<h3 class="${q.ok?'passed':'failed'}">${q.mode.name} · ${q.ok?'corredor por estudiar':'replantear pendiente'}</h3><div class="lab-metrics">${metric(number(q.trips,0),'Viajes para esa carga')}${metric(number(q.tripHours*60)+' min','Tiempo de trayecto a velocidad nominal')}${metric(number(q.excavationM3)+' m³','Excavación estimada')}${metric(number(q.reusableM3)+' m³','Material potencialmente aprovechable')}</div><p><b>Red:</b> ${q.mode.network}<br><b>Estudio:</b> ${q.mode.study}<br><b>Terminales:</b> ${q.mode.terminal}</p>${q.issues.length?'<ul>'+q.issues.map(r=>'<li>'+r+'</li>').join('')+'</ul>':''}<h4>Presupuesto orientativo de juego</h4>${price(q.cost)}<p>Descarte: ${number(q.discardM3)} m³ · árido de firme: ${number(q.aggregateM3)} m³. El material aprovechable debe excavarse, estudiarse y transportarse; aquí no se añade al inventario. El coste del corredor no incluye terminales ni puentes.</p>`;}
 else{const q=defenseStudy(o);$('#lab-results').innerHTML=`<h3 class="${q.ok?'passed':'failed'}">${q.ok?'Emplazamiento condicionado':'Emplazamiento insuficiente'}</h3><div class="lab-metrics">${metric(number(q.coverage*100)+'%','Sector de visión despejado')}${metric(q.needsPower?'Sí':'No','Requiere energía')}</div><p>${q.details}</p>${q.reasons.length?'<ul>'+q.reasons.map(r=>'<li class="failed">'+r+'</li>').join('')+'</ul>':'<p>Falta completar estudio, suministro y personal para llevar este diseño a campaña.</p>'}<h4>Plataforma y acceso · presupuesto de juego</h4>${price(q.cost)}`;}}catch(e){$('#lab-results').innerHTML='<p class="failed">'+esc(e.message)+'</p>';}}
$('#lab-form').addEventListener('submit',e=>e.preventDefault());$('#lab-form').addEventListener('input',calculate);$('#lab-form').addEventListener('change',calculate);
$('#art-direction').innerHTML='<img src="./assets/design/architecture-standard-v1.png" loading="lazy" alt="Dirección artística original: aldea integrada en el entorno y diez etapas arquitectónicas"><p>Dirección artística de arquitectura. Esta ilustración fija el objetivo; los modelos programados se consultan en Edificios.</p><img src="./assets/design/civilizations-standard-v1.png" loading="lazy" alt="Seis pueblos originales: humanos, Verdantes, Pétreos, Mareanos, Sintéticos y Astrales"><p>Dirección artística de los seis pueblos. Sus modelos y condiciones de campaña se distinguen en Civilizaciones.</p>';
const qs=new URLSearchParams(location.search),kind=qs.get('section');chooseSection(kind&&['buildings','units','npcs','civilizations','engineering','standard'].includes(kind)?kind:'buildings');if(qs.has('id')&&registry()[qs.get('id')]){selected=qs.get('id');era=Math.max(0,registry()[selected].era||0);renderLibrary();renderItem();}function frame(t){if(currentModel&&['units','npcs'].includes(section)){animateUnit(currentModel,{type:currentModel.userData.type||'settler'},t/1000,true,false,false);dirty=true;}if(dirty)renderView();requestAnimationFrame(frame);}requestAnimationFrame(frame);
export function exportLevel(kind,id,e,l){if(!Number.isInteger(l)||l<1||l>10)throw Error('Nivel inválido');return thumbnail(kind,id,e,l);}
export function coverage(){return{buildings:Object.keys(BUILDINGS).length,units:Object.keys(UNITS).length,npcs:NPCS.length,civilizations:Object.keys(CIVILIZATIONS).length,eras:ERAS.length,levels:10,selected,era,level,section};}

if('serviceWorker' in navigator&&(location.protocol==='https:'||location.hostname==='127.0.0.1'))navigator.serviceWorker.register('./sw.js').catch(()=>{});
